import { describe, it, expect } from 'vitest';
import { HeroMapper } from '../../../src/data/mappers/HeroMapper';

describe('HeroMapper', () => {
  describe('toHero', () => {
    it('maps an unprefixed npc name to an empty picture', () => {
      const result = HeroMapper.toHero('antimage');
      expect(result.picture).toBe('');
    });
  });
});
```

This test verifies that when `toHero` is called with an NPC name that lacks the 'npc_dota_hero_' prefix (like 'antimage'), the resulting hero object has an empty string for the picture property.

