import { HeroRepository } from '../../../domain/HeroRepository';

describe('GetHeroesUseCase', () => {
  it('rejects when the repository rejects', async () => {
    // Create a mock repository that throws an error
    const mockRepository: HeroRepository = {
      getHeroes: () => Promise.reject(new Error('Repository error'))
    };

    // Create the use case with the mock repository
    const useCase = new GetHeroesUseCase(mockRepository);

    // Verify that execute() rejects with the same error
    await expect(useCase.execute()).rejects.toThrow('Repository error');
  });
});
```

This test ensures that any errors thrown by the repository are properly propagated through the use case to the caller. The test will fail if the use case doesn't correctly handle and propagate repository errors.

